package com.mis.mis_backend.course;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/courses") public class CourseController{private final CourseService s;public CourseController(CourseService s){this.s=s;}@GetMapping public List<Course> getAllCourses(){return s.getAllCourses();}@PostMapping public Course createCourse(@RequestBody Course c){return s.createCourse(c);}}